export function MenuExample() {
  const [checked, setChecked] = useState(false)
  const [format, setFormat] = useState('plain')
  return <Menu label="Item actions" triggerElement={<Button>More item actions</Button>} items={[
    { id: 'rename', label: 'Rename item', group: 'Manage' },
    { id: 'metadata', label: 'Include metadata', group: 'Export options', selection: 'checkbox', checked },
    { id: 'plain', label: 'Plain text', group: 'Format', selection: 'radio', radioGroup: 'format', checked: format === 'plain' },
    { id: 'markdown', label: 'Markdown', group: 'Format', selection: 'radio', radioGroup: 'format', checked: format === 'markdown' },
    { id: 'open', label: 'Open item', group: 'Links', href: '/items/current', description: 'View the selected item', shortcut: '⌘O' },
  ]} onSelect={id => { if (id === 'plain' || id === 'markdown') setFormat(id) }} onCheckedChange={(id, value) => { if (id === 'metadata') setChecked(value) }} />
}

