import 'brutalist-design-system/styles.css'
import 'brutalist-design-system/styles.css'
import { useState } from 'react'
import { Table } from 'brutalist-design-system'
import type { TableSort } from 'brutalist-design-system'

const records = [
  { id: 'north', name: 'North studio', owner: 'Mira' },
  { id: 'west', name: 'West studio', owner: 'Jonas' },
  { id: 'archive', name: 'Archive', owner: 'Rae', unavailable: true },
]

export function SelectionExample() {
  const [selectedIds, setSelectedIds] = useState<string[]>(['previous-page'])
  const [sort, setSort] = useState<TableSort | undefined>()
  return <Table label="Studios" rows={records} rowKey={row => row.id} sort={sort} onSort={setSort}
    selection={{ selectedIds, onSelectionChange: setSelectedIds, rowLabel: row => row.name, isRowSelectable: row => !row.unavailable }}
    columns={[
      { id: 'name', header: 'Studio', sortable: true, render: row => row.name },
      { id: 'owner', header: 'Owner', render: row => row.owner },
      { id: 'actions', header: 'Actions', align: 'end', render: () => 'Open' },
    ]} />
}

