import 'brutalist-design-system/styles.css'
import 'brutalist-design-system/styles.css'
import { useState } from 'react'
import { SidebarPanel } from 'brutalist-design-system'

export function SidebarPanelExample() {
  const [projects, setProjects] = useState([
    { id: 'north-cove', title: 'North cove transect', pinned: true },
    { id: 'tide-pools', title: 'Tide-pool census', pinned: false },
    { id: 'dune-flora', title: 'Dune flora survey', pinned: false },
  ])
  return <SidebarPanel
    brand={{ label: 'Fieldworks' }}
    primaryAction={{ label: 'New project', onClick: () => setProjects(list => [...list, { id: `project-${list.length + 1}`, title: 'Untitled project', pinned: false }]) }}
    navigation={[
      { id: 'projects', label: 'Projects', href: '#projects', icon: 'folder', current: true },
      { id: 'settings', label: 'Settings', href: '#settings', icon: 'settings' },
    ]}
    projects={projects.map(project => ({
      ...project,
      href: `#${project.id}`,
      actions: [
        { id: 'pin', label: project.pinned ? 'Unpin' : 'Pin', icon: 'Pin' as const },
        { id: 'delete', label: 'Delete', icon: 'delete' as const, danger: true },
      ],
    }))}
    onProjectAction={(id, action) => {
      if (action === 'pin') setProjects(list => list.map(project => project.id === id ? { ...project, pinned: !project.pinned } : project))
      if (action === 'delete') setProjects(list => list.filter(project => project.id !== id))
    }}
    account={{ label: 'Mara Venn', actions: [{ id: 'profile', label: 'Your profile' }, { id: 'sign-out', label: 'Sign out' }], onAction: () => undefined }}
  />
}

