import 'brutalist-design-system/styles.css'
import 'brutalist-design-system/styles.css'
import { useState } from 'react'
import { PromptInput } from 'brutalist-design-system'
import type { FileItem } from 'brutalist-design-system'

export function PromptInputExample() {
  const [value, setValue] = useState('Summarize the spring survey and list open questions.')
  const [files, setFiles] = useState<FileItem[]>([{ id: 'survey', name: 'spring-survey.pdf', size: 24000 }])
  const [busy, setBusy] = useState(false)
  const [style, setStyle] = useState('balanced')
  return <PromptInput
    value={value}
    onChange={setValue}
    selector={{
      label: 'Response style',
      value: style,
      onChange: setStyle,
      options: [
        { id: 'brief', label: 'Brief', description: 'A few sentences.' },
        { id: 'balanced', label: 'Balanced', description: 'Key points with context.' },
        { id: 'thorough', label: 'Thorough', description: 'Full detail and sources.' },
      ],
    }}
    files={files}
    onAttach={added => setFiles(current => [...current, ...added.map(file => ({ id: file.name, name: file.name, size: file.size }))])}
    onRemove={id => setFiles(current => current.filter(file => file.id !== id))}
    busy={busy}
    onSubmit={() => {
      setBusy(true)
      window.setTimeout(() => { setBusy(false); setValue('') }, 1200)
    }}
  />
}

