import 'brutalist-design-system/styles.css'
import 'brutalist-design-system/styles.css'
import { useEffect, useRef, useState } from 'react'
import { SubscriptionSection } from 'brutalist-design-system'
import type { SubmissionState } from 'brutalist-design-system'

function useSimulatedSubscription({ failFirstAttempt = false } = {}) {
  // SIMULATION ONLY: nothing is sent and no address is stored. Replace `submit` with your
  // mailing-list request and report its real outcome through `state`.
  const [state, setState] = useState<SubmissionState>({ status: 'idle' })
  const attempts = useRef(0)
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  useEffect(() => () => clearTimeout(timer.current), [])
  function submit(email: string) {
    attempts.current += 1
    const failed = failFirstAttempt && attempts.current === 1
    setState({ status: 'pending' })
    timer.current = setTimeout(() => setState(failed
      ? { status: 'error', message: 'We couldn’t add your address just now. Please try again.' }
      : { status: 'success', message: `Thanks. The next letter will go to ${email}.` }), 900)
  }
  return { state, submit, reset: () => setState(current => current.status === 'pending' ? current : { status: 'idle' }) }
}

export function CompactSubscriptionExample() {
  const [email, setEmail] = useState('')
  const subscription = useSimulatedSubscription()
  return <SubscriptionSection
    title="Notes from the workshop"
    description="A short monthly letter on keeping and connecting working notes."
    email={email}
    onEmailChange={value => { setEmail(value); subscription.reset() }}
    onSubmit={subscription.submit}
    state={subscription.state}
    consentText="Receive the monthly workshop letter from Commonplace. Unsubscribe from any issue."
    privacy={{ label: 'Privacy notice', href: '#privacy' }}
  />
}

